const D = { density:.55, energy:.6, speed:1, scale:1, wind:.5, hue:330, x:.5, y:.5, style:'blossom', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
const sec = K.section | 0;

// per-frame deterministic PRNG (reset each frame so the tree STRUCTURE is stable; wind is added separately)
let sr;
function rreset(){ sr = ((P.seed + 1 + sec*777) * 2654435761) >>> 0; }
function rnd(){ sr ^= sr<<13; sr>>>=0; sr ^= sr>>17; sr ^= sr<<5; sr>>>=0; return sr/4294967295; }

// wind: SUM of incommensurate sinusoids so the pose NEVER re-phases at the 8s validation window
const wt = K.t;
const gust = 0.9*Math.sin(wt*0.61) + 0.5*Math.sin(wt*1.43 + 1.7) + 0.32*Math.sin(wt*2.29 + 0.4);
const windAmp = (0.05 + P.wind*0.16) * (1 + A.lowmid*0.5);
const maxDepth = 9 + Math.round(P.density*2);           // 9..11
const ratio = 0.70 + P.scale*0.06;
const spread = 0.34 + P.wind*0.10;
const len0 = height * (0.16 + P.scale*0.07);
const hb = P.hue;

// ---- sky/ground ground so it's never near-black and fills frame ----
let sky0, sky1, grd0;
if (style === 'blossom')      { sky0='#101a2e'; sky1='#26304e'; grd0='#0b0d16'; }
else if (style === 'autumn')  { sky0='#241426'; sky1='#3a2030'; grd0='#120a10'; }
else if (style === 'bio')     { sky0='#02060a'; sky1='#04121a'; grd0='#010406'; }
else if (style === 'winter')  { sky0='#0c1420'; sky1='#1c2c3e'; grd0='#0a0e14'; }
else                          { sky0='#efe9dc'; sky1='#dcd2c0'; grd0='#cfc4ae'; } // ink (paper)
const dc = drawingContext;
const gg = dc.createLinearGradient(0,0,0,height);
gg.addColorStop(0, sky0); gg.addColorStop(0.62, sky1); gg.addColorStop(1, grd0);
dc.save(); dc.fillStyle = gg; dc.fillRect(0,0,width,height); dc.restore();

const inkMode = (style === 'ink');
const rootX = width * P.x, rootY = height * (0.995);
push();
if (inkMode) blendMode(BLEND); else blendMode(ADD);
strokeCap(ROUND);

function branch(x, y, ang, len, depth) {
  const df = maxDepth - depth;                          // 0 at root -> maxDepth at tips
  const tf = df / maxDepth;
  // sway grows toward the tips (cumulative feel) + a per-node phase for organic variation
  const nodePhase = rnd() * 6.28;
  const sway = windAmp * (0.15 + tf*tf*1.6) * (gust + 0.4*Math.sin(wt*1.9 + nodePhase));
  const a = ang + sway;
  const ex = x + Math.cos(a) * len, ey = y - Math.sin(a) * len;

  const w = Math.max(0.5, (maxDepth - df) * 0.9 * (0.6 + P.scale*0.5));
  // trunk brown -> tip hue
  let sh, ss, sv, sa;
  if (inkMode) { sh = 30; ss = 8; sv = 12; sa = 90; }
  else if (style === 'bio') { sh = wh(hb + 70 + tf*60); ss = 70; sv = 40 + tf*60; sa = 30 + tf*30; }
  else { const trunk = 26; sh = wh(trunk + (hb - trunk)*tf); ss = 30 + tf*45; sv = 22 + tf*55; sa = 26 + tf*34; }
  stroke(sh, ss, sv, sa * (0.6 + P.energy*0.6));
  strokeWeight(w);
  line(x, y, ex, ey);

  if (depth <= 0 || len < u*0.012) {
    // foliage tip: blossom / leaf dot
    const bs = u * (0.006 + rnd()*0.012) * (0.7 + P.density*0.9);
    noStroke();
    let fh, fs, fv, fa;
    if (inkMode)              { fh=30; fs=6; fv=20; fa=40; }
    else if (style==='autumn'){ fh=wh(18 + rnd()*36); fs=85; fv=95; fa=55; }
    else if (style==='bio')   { fh=wh(hb+120+rnd()*80); fs=80; fv=100; fa=60; }
    else if (style==='winter'){ fh=wh(200+rnd()*30); fs=20; fv=100; fa=55; }
    else                      { fh=wh(hb + (rnd()-0.5)*40); fs=60+rnd()*30; fv=95; fa=55; } // blossom
    const tw = fa + A.treble*30 + K.pulse*10;
    fill(fh, fs, fv, Math.min(90, tw));
    circle(ex + (rnd()-0.5)*bs, ey + (rnd()-0.5)*bs, bs*2);
    return;
  }
  const nb = (rnd() < 0.30 && df < maxDepth-2) ? 3 : 2;  // occasional trifurcation
  const nl = len * (ratio + (rnd()-0.5)*0.06);
  const sp = spread * (0.7 + rnd()*0.6);
  branch(ex, ey, a + sp, nl, depth-1);
  branch(ex, ey, a - sp*(0.8+rnd()*0.4), nl, depth-1);
  if (nb === 3) branch(ex, ey, a + (rnd()-0.5)*0.3, nl*0.9, depth-1);
}

rreset();
branch(rootX, rootY, Math.PI/2 + 0.10*Math.sin(wt*0.37), len0, maxDepth);
blendMode(BLEND);
pop();
